WITH lines AS (SELECT id, service, host, level, latency_ms, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS k, attr_value) SELECT CASE WHEN latency_ms >= 2342 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, SIZE(COLLECT_SET(k)) AS num_ks, SUM(CASE WHEN host = 'h3' THEN latency_ms ELSE 0 END) AS h3_latency_ms, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN service = 'search' THEN 1 END), 0), 2) AS latency_ms_per_search, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, APPROX_PERCENTILE(latency_ms, 0.5) AS latency_ms_p50, COUNT(CASE WHEN service = 'billing' THEN 1 END) AS billing_count FROM lines GROUP BY 1 ORDER BY latency_ms_stddev ASC
